import { useState, useMemo } from 'react';
import {
  BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer, Cell
} from 'recharts';
import { filterData, formatKRW } from '../utils/calcMetrics';
import './AbcAnalysis.css';

export default function AbcAnalysis({ allData, filters }) {
  const [tabMode, setTabMode] = useState('product'); // product | store

  // 상품 ABC 분석
  const productAbcData = useMemo(() => {
    const filtered = filterData(allData, filters);
    const productMap = {};

    filtered.forEach((file) => {
      file.products.forEach((prod) => {
        const key = prod.code;
        if (!productMap[key]) {
          productMap[key] = {
            code: prod.code,
            name: prod.name,
            midCat: prod.midCat,
            totalSales: 0,
          };
        }
        productMap[key].totalSales += prod.totalSales || 0;
      });
    });

    const products = Object.values(productMap).sort((a, b) => b.totalSales - a.totalSales);
    const totalSales = products.reduce((s, p) => s + p.totalSales, 0);

    let cumulativeSales = 0;
    return products.map((p) => {
      cumulativeSales += p.totalSales;
      const cumulativePct = totalSales > 0 ? (cumulativeSales / totalSales) * 100 : 0;
      let classification = 'C';
      if (cumulativePct <= 80) classification = 'A';
      else if (cumulativePct <= 95) classification = 'B';

      return {
        ...p,
        cumulativePct,
        classification,
        salesPct: totalSales > 0 ? (p.totalSales / totalSales) * 100 : 0,
      };
    });
  }, [allData, filters]);

  // 매장 ABC 분석
  const storeAbcData = useMemo(() => {
    const filtered = filterData(allData, filters);
    const storeMap = {};

    filtered.forEach((file) => {
      if (!storeMap[file.store]) {
        storeMap[file.store] = {
          store: file.store,
          totalSales: 0,
        };
      }
      storeMap[file.store].totalSales += file.totalSales || 0;
    });

    const stores = Object.values(storeMap).sort((a, b) => b.totalSales - a.totalSales);
    const totalSales = stores.reduce((s, st) => s + st.totalSales, 0);

    let cumulativeSales = 0;
    return stores.map((st) => {
      cumulativeSales += st.totalSales;
      const cumulativePct = totalSales > 0 ? (cumulativeSales / totalSales) * 100 : 0;
      let classification = 'C';
      if (cumulativePct <= 80) classification = 'A';
      else if (cumulativePct <= 95) classification = 'B';

      return {
        ...st,
        cumulativePct,
        classification,
        salesPct: totalSales > 0 ? (st.totalSales / totalSales) * 100 : 0,
      };
    });
  }, [allData, filters]);

  const currentData = tabMode === 'product' ? productAbcData : storeAbcData;
  const chartData = currentData.map((item, idx) => ({
    ...item,
    index: idx + 1,
    label: tabMode === 'product' ? item.name : item.store,
  }));

  // 차트용 데이터 (축약)
  const chartDisplay = chartData.slice(0, 20).map((item) => ({
    label: item.label,
    sales: item.totalSales,
    cumulative: item.cumulativePct,
  }));

  const getClassificationColor = (cls) => {
    if (cls === 'A') return '#16a34a';
    if (cls === 'B') return '#fbbf24';
    return '#ef4444';
  };

  const getClassificationLabel = (cls) => {
    if (cls === 'A') return 'A등급';
    if (cls === 'B') return 'B등급';
    return 'C등급';
  };

  if (allData.length === 0) {
    return <div className="daily-empty">파일을 먼저 업로드해주세요.</div>;
  }

  return (
    <div className="abc-analysis">
      {/* 탭 */}
      <div className="tab-bar">
        <button
          className={`tab-btn ${tabMode === 'product' ? 'active' : ''}`}
          onClick={() => setTabMode('product')}
        >
          상품 ABC
        </button>
        <button
          className={`tab-btn ${tabMode === 'store' ? 'active' : ''}`}
          onClick={() => setTabMode('store')}
        >
          매장 ABC
        </button>
      </div>

      {/* 파레토 차트 */}
      <div className="chart-card">
        <div className="chart-title">
          {tabMode === 'product' ? '상품' : '매장'} ABC 파레토 차트
        </div>
        <ResponsiveContainer width="100%" height={320}>
          <BarChart data={chartDisplay} margin={{ top: 10, right: 60, left: 10, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis dataKey="label" tick={{ fontSize: 10 }} angle={-45} textAnchor="end" height={80} />
            <YAxis yAxisId="left" tickFormatter={formatKRW} tick={{ fontSize: 11 }} />
            <YAxis yAxisId="right" orientation="right" label={{ value: '%', angle: 90, position: 'insideRight', offset: 10 }} tick={{ fontSize: 11 }} />
            <Tooltip
              formatter={(v, name) => {
                if (name === 'sales') return [`${formatKRW(v)}원`, '매출'];
                if (name === 'cumulative') return [`${v.toFixed(1)}%`, '누적 %'];
                return [v, name];
              }}
            />
            <Legend />
            <Bar yAxisId="left" dataKey="sales" fill="#1d4ed8" name="매출" />
            <Line
              yAxisId="right"
              type="monotone"
              dataKey="cumulative"
              stroke="#dc2626"
              strokeWidth={2}
              dot={{ r: 3 }}
              name="누적 %"
            />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* ABC 분석 통계 */}
      <div className="abc-summary">
        {['A', 'B', 'C'].map((grade) => {
          const items = currentData.filter((d) => d.classification === grade);
          const totalSales = items.reduce((s, i) => s + i.totalSales, 0);
          const allTotalSales = currentData.reduce((s, i) => s + i.totalSales, 0);
          const salesPct = allTotalSales > 0 ? (totalSales / allTotalSales) * 100 : 0;
          return (
            <div key={grade} className="summary-card" style={{ borderLeftColor: getClassificationColor(grade) }}>
              <div className="summary-grade">{grade}등급</div>
              <div className="summary-count">{items.length}개</div>
              <div className="summary-sales">{formatKRW(totalSales)}원</div>
              <div className="summary-pct">{salesPct.toFixed(1)}%</div>
            </div>
          );
        })}
      </div>

      {/* 상세 테이블 */}
      <div className="chart-card">
        <div className="chart-title">
          {tabMode === 'product' ? '상품' : '매장'} ABC 분류 목록
        </div>
        <table className="data-table">
          <thead>
            <tr>
              <th>순위</th>
              <th>{tabMode === 'product' ? '상품명' : '매장명'}</th>
              {tabMode === 'product' && <th>중분류</th>}
              <th>매출</th>
              <th>비율</th>
              <th>누적 비율</th>
              <th>등급</th>
            </tr>
          </thead>
          <tbody>
            {chartData.map((item) => (
              <tr key={tabMode === 'product' ? item.code : item.store}>
                <td style={{ textAlign: 'center', fontWeight: 600 }}>{item.index}</td>
                <td className="td-store">{item.label}</td>
                {tabMode === 'product' && <td>{item.midCat}</td>}
                <td className="td-num">{formatKRW(item.totalSales)}원</td>
                <td className="td-num">{item.salesPct.toFixed(1)}%</td>
                <td className="td-num">{item.cumulativePct.toFixed(1)}%</td>
                <td>
                  <span
                    className="badge"
                    style={{
                      backgroundColor: getClassificationColor(item.classification),
                      color: '#fff',
                    }}
                  >
                    {getClassificationLabel(item.classification)}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
