import { useState } from 'react';
import * as XLSX from 'xlsx';
import { formatKRW, filterData, aggregateByMonth, aggregateByStore } from '../utils/calcMetrics';
import './ExportReport.css';

export default function ExportReport({ allData, opData, filters }) {
  const [exporting, setExporting] = useState(false);

  const handleExportToExcel = async () => {
    if (allData.length === 0) {
      alert('내보낼 데이터가 없습니다.');
      return;
    }

    setExporting(true);

    try {
      const wb = XLSX.utils.book_new();

      // Sheet 1: 개요
      const overviewData = prepareOverviewData();
      XLSX.utils.book_append_sheet(
        wb,
        XLSX.utils.aoa_to_sheet(overviewData),
        '개요'
      );

      // Sheet 2: 월별 추이
      const monthlyData = prepareMonthlyData();
      XLSX.utils.book_append_sheet(
        wb,
        XLSX.utils.aoa_to_sheet(monthlyData),
        '월별추이'
      );

      // Sheet 3: 매장 상세
      const storeData = prepareStoreDetailData();
      XLSX.utils.book_append_sheet(
        wb,
        XLSX.utils.aoa_to_sheet(storeData),
        '매장상세'
      );

      // Sheet 4: 상품 믹스
      const productData = prepareProductMixData();
      XLSX.utils.book_append_sheet(
        wb,
        XLSX.utils.aoa_to_sheet(productData),
        '상품구성'
      );

      // Sheet 5: 주간 리포트
      const weeklyData = prepareWeeklyData();
      XLSX.utils.book_append_sheet(
        wb,
        XLSX.utils.aoa_to_sheet(weeklyData),
        '주간리포트'
      );

      // 파일 다운로드
      const filename = `brand-analytics-report-${new Date().toISOString().slice(0, 10)}.xlsx`;
      XLSX.writeFile(wb, filename);

      alert('✅ 엑셀 파일 다운로드가 완료되었습니다.');
    } catch (error) {
      console.error('Export error:', error);
      alert('❌ 내보내기 중 오류가 발생했습니다.');
    } finally {
      setExporting(false);
    }
  };

  const prepareOverviewData = () => {
    const stores = aggregateByStore(filterData(allData, filters), {});
    const totalSales = stores.reduce((s, st) => s + st.totalSales, 0);

    return [
      ['브랜드 매출 분석 리포트'],
      ['생성일시', new Date().toLocaleString('ko-KR')],
      ['필터', `연도: ${filters.year || 'All'}, 매장: ${filters.stores?.join(', ') || 'All'}`],
      [],
      ['전체 현황'],
      ['총 매출', `${formatKRW(totalSales)}원`],
      ['매장 수', stores.length],
      [],
      ['매장별 현황'],
      ['매장', '매출', '구성비'],
      ...stores
        .sort((a, b) => b.totalSales - a.totalSales)
        .map((st) => [
          st.store,
          `${formatKRW(st.totalSales)}원`,
          `${((st.totalSales / totalSales) * 100).toFixed(1)}%`,
        ]),
    ];
  };

  const prepareMonthlyData = () => {
    const monthly = aggregateByMonth(filterData(allData, filters), {});

    return [
      ['월별 매출 현황'],
      ['연월', '매출'],
      ...monthly.map((m) => [m.yearMonth, `${formatKRW(m.totalSales)}원`]),
    ];
  };

  const prepareStoreDetailData = () => {
    const filtered = filterData(allData, filters);
    const stores = [...new Set(filtered.map((d) => d.store))].sort();

    const result = [
      ['매장별 상세 데이터'],
      [],
    ];

    stores.forEach((store) => {
      const storeData = filtered.filter((d) => d.store === store);
      const totalSales = storeData.reduce((s, d) => s + d.totalSales, 0);
      const months = storeData.map((d) => `${d.year}-${String(d.month).padStart(2, '0')}`);

      result.push([store]);
      result.push(['총 매출', `${formatKRW(totalSales)}원`]);
      result.push(['데이터 기간', `${Math.min(...months)} ~ ${Math.max(...months)}`]);
      result.push([]);
    });

    return result;
  };

  const prepareProductMixData = () => {
    const filtered = filterData(allData, filters);
    const prodMap = {};

    filtered.forEach((d) => {
      d.products.forEach((prod) => {
        const key = prod.code;
        if (!prodMap[key]) {
          prodMap[key] = {
            name: prod.name,
            midCat: prod.midCat,
            totalQty: 0,
            totalSales: 0,
          };
        }
        prodMap[key].totalQty += prod.totalQty || 0;
        prodMap[key].totalSales += prod.totalSales || 0;
      });
    });

    const products = Object.values(prodMap)
      .sort((a, b) => b.totalSales - a.totalSales)
      .slice(0, 50);

    const totalSales = products.reduce((s, p) => s + p.totalSales, 0);

    return [
      ['상품별 구성'],
      ['상품명', '중분류', '판매량', '매출', '구성비'],
      ...products.map((p) => [
        p.name,
        p.midCat,
        p.totalQty,
        `${formatKRW(p.totalSales)}원`,
        `${((p.totalSales / totalSales) * 100).toFixed(1)}%`,
      ]),
    ];
  };

  const prepareWeeklyData = () => {
    const filtered = filterData(allData, filters);
    const weekMap = {};

    filtered.forEach((d) => {
      d.dailyTotals.forEach((day) => {
        if (!day.date) return;
        const date = new Date(day.date);
        if (isNaN(date)) return;

        const target = new Date(date);
        target.setDate(target.getDate() - target.getDay() + (target.getDay() === 0 ? -6 : 1));
        const week1 = new Date(target.getFullYear(), 0, 4);
        week1.setDate(week1.getDate() - week1.getDay() + (week1.getDay() === 0 ? -6 : 1));
        const dayDiff = (target - week1) / 86400000;
        const weekNum = Math.floor(dayDiff / 7) + 1;

        const key = `${date.getFullYear()}-W${String(weekNum).padStart(2, '0')}`;
        if (!weekMap[key]) {
          weekMap[key] = { sales: 0, txCount: 0, dayCount: 0 };
        }
        weekMap[key].sales += day.sales || 0;
        weekMap[key].txCount += day.txCount || 0;
        weekMap[key].dayCount += 1;
      });
    });

    return [
      ['주간 리포트'],
      ['주차', '총 매출', '일 평균 매출', '총 영수건수'],
      ...Object.entries(weekMap)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([week, data]) => [
          week,
          `${formatKRW(data.sales)}원`,
          `${formatKRW(Math.round(data.sales / data.dayCount))}원`,
          data.txCount,
        ]),
    ];
  };

  return (
    <div className="export-report">
      <div className="chart-card">
        <div className="chart-title">리포트 내보내기</div>
        <div className="export-description">
          현재 필터가 적용된 모든 데이터를 Excel 파일로 내보냅니다.
          <br />
          포함되는 시트:
          <ul>
            <li>개요: 전체 현황 및 매장별 집계</li>
            <li>월별추이: 월별 매출 추이</li>
            <li>매장상세: 매장별 상세 정보</li>
            <li>상품구성: TOP 50 상품 구성</li>
            <li>주간리포트: 주간 단위 분석</li>
          </ul>
        </div>

        <button
          className="export-button"
          onClick={handleExportToExcel}
          disabled={exporting || allData.length === 0}
        >
          {exporting ? '⏳ 내보내는 중...' : '📥 Excel 파일로 다운로드'}
        </button>
      </div>

      <div className="chart-card">
        <div className="chart-title">파일 정보</div>
        <table className="info-table">
          <tbody>
            <tr>
              <td className="info-label">선택된 데이터:</td>
              <td>{allData.length}건 (매장×월)</td>
            </tr>
            <tr>
              <td className="info-label">년도:</td>
              <td>{filters.year || '전체'}</td>
            </tr>
            <tr>
              <td className="info-label">매장:</td>
              <td>{filters.stores?.join(', ') || '전체'}</td>
            </tr>
            <tr>
              <td className="info-label">월:</td>
              <td>{filters.months?.join(', ') || '전체'}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}
