import { useMemo } from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer
} from 'recharts';
import { filterData, formatKRW, formatShort } from '../utils/calcMetrics';
import './WeeklyReport.css';

export default function WeeklyReport({ allData, filters }) {
  // ISO 주차별 데이터
  const weeklyData = useMemo(() => {
    const filtered = filterData(allData, filters);
    const weekMap = {};

    filtered.forEach((d) => {
      d.dailyTotals.forEach((day) => {
        if (!day.date) return;
        const date = new Date(day.date);
        if (isNaN(date)) return;

        // ISO 주차 계산
        const target = new Date(date);
        target.setDate(target.getDate() - target.getDay() + (target.getDay() === 0 ? -6 : 1));
        const week1 = new Date(target.getFullYear(), 0, 4);
        week1.setDate(week1.getDate() - week1.getDay() + (week1.getDay() === 0 ? -6 : 1));
        const dayDiff = (target - week1) / 86400000;
        const weekNum = Math.floor(dayDiff / 7) + 1;

        const key = `${date.getFullYear()}-W${String(weekNum).padStart(2, '0')}`;
        if (!weekMap[key]) {
          weekMap[key] = {
            week: key,
            startDate: target,
            sales: 0,
            txCount: 0,
            dayCount: 0,
          };
        }
        weekMap[key].sales += day.sales || 0;
        weekMap[key].txCount += day.txCount || 0;
        weekMap[key].dayCount += 1;
      });
    });

    return Object.values(weekMap)
      .sort((a, b) => a.week.localeCompare(b.week))
      .map((w) => ({
        ...w,
        avgSales: w.dayCount > 0 ? w.sales / w.dayCount : 0,
        avgTx: w.dayCount > 0 ? w.txCount / w.dayCount : 0,
        dateRange: formatDateRange(w.startDate),
      }));
  }, [allData, filters]);

  if (allData.length === 0) {
    return <div className="daily-empty">파일을 먼저 업로드해주세요.</div>;
  }

  return (
    <div className="weekly-report">
      {/* 주간 매출 차트 */}
      <div className="chart-card">
        <div className="chart-title">주간 매출 추이</div>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={weeklyData} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis dataKey="week" tick={{ fontSize: 10 }} angle={-45} textAnchor="end" height={60} />
            <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
            <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
            <Bar dataKey="sales" fill="#0d2258" name="주간 매출" />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* 주간 데이터 테이블 */}
      <div className="chart-card">
        <div className="chart-title">주간 상세 현황</div>
        <table className="data-table">
          <thead>
            <tr>
              <th>주차</th>
              <th>기간</th>
              <th>일수</th>
              <th>총 매출</th>
              <th>일 평균 매출</th>
              <th>총 영수건수</th>
              <th>일 평균 영수건수</th>
            </tr>
          </thead>
          <tbody>
            {weeklyData.map((w) => (
              <tr key={w.week}>
                <td style={{ fontWeight: 600 }}>{w.week}</td>
                <td className="td-store">{w.dateRange}</td>
                <td className="td-num">{w.dayCount}일</td>
                <td className="td-num">{formatKRW(w.sales)}원</td>
                <td className="td-num">{formatKRW(Math.round(w.avgSales))}원</td>
                <td className="td-num">{formatKRW(w.txCount)}건</td>
                <td className="td-num">{formatKRW(Math.round(w.avgTx))}건</td>
              </tr>
            ))}
            <tr className="total-row">
              <td colSpan="2">합계</td>
              <td className="td-num">{weeklyData.reduce((s, w) => s + w.dayCount, 0)}일</td>
              <td className="td-num">{formatKRW(weeklyData.reduce((s, w) => s + w.sales, 0))}원</td>
              <td className="td-num">
                {formatKRW(
                  Math.round(
                    weeklyData.reduce((s, w) => s + w.sales, 0) /
                    Math.max(weeklyData.reduce((s, w) => s + w.dayCount, 0), 1)
                  )
                )}
                원
              </td>
              <td className="td-num">{formatKRW(weeklyData.reduce((s, w) => s + w.txCount, 0))}건</td>
              <td className="td-num">
                {formatKRW(
                  Math.round(
                    weeklyData.reduce((s, w) => s + w.txCount, 0) /
                    Math.max(weeklyData.reduce((s, w) => s + w.dayCount, 0), 1)
                  )
                )}
                건
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

function formatDateRange(startDate) {
  const endDate = new Date(startDate);
  endDate.setDate(endDate.getDate() + 6);

  const format = (d) => `${d.getMonth() + 1}.${d.getDate()}`;
  return `${format(startDate)} ~ ${format(endDate)}`;
}
