import { useState, useMemo } from 'react';
import {
  ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell
} from 'recharts';
import { formatKRW, filterData } from '../utils/calcMetrics';
import './MenuEngineering.css';

export default function MenuEngineering({ allData, filters }) {
  const [selectedMidCat, setSelectedMidCat] = useState('');

  // 상품별 수량/매출 평균 계산
  const productStats = useMemo(() => {
    const filtered = filterData(allData, filters);
    const productMap = {};

    filtered.forEach((file) => {
      file.products.forEach((prod) => {
        const key = `${prod.code}`;
        if (!productMap[key]) {
          productMap[key] = {
            code: prod.code,
            name: prod.name,
            mainCat: prod.mainCat,
            midCat: prod.midCat,
            subCat: prod.subCat,
            totalQty: 0,
            totalSales: 0,
            count: 0,
          };
        }
        productMap[key].totalQty += prod.totalQty || 0;
        productMap[key].totalSales += prod.totalSales || 0;
        productMap[key].count += 1;
      });
    });

    return Object.values(productMap)
      .map((p) => ({
        ...p,
        avgQty: p.count > 0 ? p.totalQty / p.count : 0,
        avgSales: p.count > 0 ? p.totalSales / p.count : 0,
      }))
      .filter((p) => p.avgQty > 0 || p.avgSales > 0);
  }, [allData, filters]);

  // 중분류 목록
  const midCategories = useMemo(() => {
    const cats = [...new Set(productStats.map((p) => p.midCat))].sort();
    return cats;
  }, [productStats]);

  // 필터링된 상품
  const filteredProducts = useMemo(() => {
    if (!selectedMidCat) return productStats;
    return productStats.filter((p) => p.midCat === selectedMidCat);
  }, [productStats, selectedMidCat]);

  // 임계값 계산 (평균)
  const meanQty = filteredProducts.reduce((s, p) => s + p.avgQty, 0) / (filteredProducts.length || 1);
  const meanSales = filteredProducts.reduce((s, p) => s + p.avgSales, 0) / (filteredProducts.length || 1);

  // 사분면 분류
  const quadrants = useMemo(() => {
    const classified = filteredProducts.map((p) => {
      let quadrant = '';
      if (p.avgQty >= meanQty && p.avgSales >= meanSales) {
        quadrant = 'Stars'; // 스타 상품
      } else if (p.avgQty >= meanQty && p.avgSales < meanSales) {
        quadrant = 'Plowhorses'; // 쟁기소 상품
      } else if (p.avgQty < meanQty && p.avgSales >= meanSales) {
        quadrant = 'Puzzles'; // 수수께끼 상품
      } else {
        quadrant = 'Dogs'; // 개 상품
      }
      return { ...p, quadrant };
    });

    const colors = {
      Stars: '#16a34a',
      Puzzles: '#d97706',
      Plowhorses: '#1d4ed8',
      Dogs: '#9ca3af',
    };

    return classified.map((p) => ({ ...p, fill: colors[p.quadrant] }));
  }, [filteredProducts, meanQty, meanSales]);

  const getQuadrantLabel = (q) => {
    const labels = {
      Stars: '스타상품',
      Puzzles: '수수께끼',
      Plowhorses: '쟁기소',
      Dogs: '개',
    };
    return labels[q] || q;
  };

  if (allData.length === 0) {
    return <div className="daily-empty">파일을 먼저 업로드해주세요.</div>;
  }

  return (
    <div className="menu-engineering">
      {/* 중분류 필터 */}
      {midCategories.length > 0 && (
        <div className="filter-group">
          <button
            className={`filter-btn ${!selectedMidCat ? 'active' : ''}`}
            onClick={() => setSelectedMidCat('')}
          >
            전체
          </button>
          {midCategories.map((cat) => (
            <button
              key={cat}
              className={`filter-btn ${selectedMidCat === cat ? 'active' : ''}`}
              onClick={() => setSelectedMidCat(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
      )}

      {/* 사분면 차트 */}
      <div className="chart-card">
        <div className="chart-title">메뉴 엔지니어링 사분면</div>
        <ResponsiveContainer width="100%" height={400}>
          <ScatterChart
            margin={{ top: 20, right: 20, bottom: 20, left: 20 }}
            data={quadrants}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis
              dataKey="avgQty"
              type="number"
              name="평균 판매량"
              label={{ value: `평균 판매량 (기준: ${meanQty.toFixed(0)}개)`, position: 'bottom', offset: 10 }}
              tick={{ fontSize: 11 }}
            />
            <YAxis
              dataKey="avgSales"
              type="number"
              name="평균 매출"
              label={{ value: `평균 매출원 (기준: ${formatKRW(meanSales)})`, angle: -90, position: 'insideLeft' }}
              tick={{ fontSize: 11 }}
            />
            <Tooltip
              cursor={{ strokeDasharray: '3 3' }}
              content={({ active, payload }) => {
                if (active && payload && payload[0]) {
                  const data = payload[0].payload;
                  return (
                    <div className="scatter-tooltip">
                      <p><strong>{data.name}</strong></p>
                      <p>판매량: {data.avgQty.toFixed(0)}개</p>
                      <p>매출: {formatKRW(data.avgSales)}원</p>
                      <p>분류: {getQuadrantLabel(data.quadrant)}</p>
                    </div>
                  );
                }
                return null;
              }}
            />
            <Scatter name="상품" data={quadrants} fill="#8884d8">
              {quadrants.map((entry) => (
                <Cell key={`cell-${entry.code}`} fill={entry.fill} />
              ))}
            </Scatter>
          </ScatterChart>
        </ResponsiveContainer>
      </div>

      {/* 범례 */}
      <div className="quadrant-legend">
        <div className="legend-item" style={{ borderLeft: '4px solid #16a34a' }}>
          <strong>스타</strong> - 높은 수량 + 높은 매출
        </div>
        <div className="legend-item" style={{ borderLeft: '4px solid #d97706' }}>
          <strong>수수께끼</strong> - 낮은 수량 + 높은 매출
        </div>
        <div className="legend-item" style={{ borderLeft: '4px solid #1d4ed8' }}>
          <strong>쟁기소</strong> - 높은 수량 + 낮은 매출
        </div>
        <div className="legend-item" style={{ borderLeft: '4px solid #9ca3af' }}>
          <strong>개</strong> - 낮은 수량 + 낮은 매출
        </div>
      </div>

      {/* 상품 분류 테이블 */}
      <div className="chart-card">
        <div className="chart-title">상품 분류 목록</div>
        <table className="data-table">
          <thead>
            <tr>
              <th>상품명</th>
              <th>중분류</th>
              <th>평균 판매량</th>
              <th>평균 매출</th>
              <th>분류</th>
            </tr>
          </thead>
          <tbody>
            {quadrants.map((p) => (
              <tr key={p.code}>
                <td className="td-store">{p.name}</td>
                <td>{p.midCat}</td>
                <td className="td-num">{p.avgQty.toFixed(0)}개</td>
                <td className="td-num">{formatKRW(p.avgSales)}원</td>
                <td>
                  <span
                    className="badge"
                    style={{ backgroundColor: p.fill, color: '#fff' }}
                  >
                    {getQuadrantLabel(p.quadrant)}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
